// Shared test helpers (only imported by *.test.ts, never by the app).
import { readFileSync } from 'node:fs';
import { CatalogEntry, HistorySet } from './types';

let realCatalog: CatalogEntry[] | null = null;

// The same static asset the app fetches at runtime, regenerated by `npm run knowledge:build`.
export function loadRealCatalog(): CatalogEntry[] {
  if (!realCatalog) {
    const url = new URL('../../../public/exercise-data/exercise_index.json', import.meta.url);
    realCatalog = JSON.parse(readFileSync(url, 'utf8')) as CatalogEntry[];
  }
  return realCatalog;
}

export const entry = (id: string, overrides: Partial<CatalogEntry> = {}): CatalogEntry => ({
  id,
  movement_pattern: 'horizontal_push',
  movement_pattern_confidence: 'high',
  movement_pattern_review_status: 'inferred',
  exercise_type: 'compound',
  equipment_access: 'gym',
  ...overrides
});

// One logged session: reps[i] at `weightKg`, timestamps a minute apart on `date`.
export const loggedSession = (exerciseId: string, date: string, weightKg: number, reps: number[], rir: number | null = 2): HistorySet[] =>
  reps.map((r, i) => ({
    exerciseId,
    weightKg,
    reps: r,
    rir,
    completedAt: `${date}T18:${String(i).padStart(2, '0')}:00.000Z`,
    setType: 'normal'
  }));
